- [ ] **Step 4: Implement `src/collect.js`**

Create `src/collect.js`:

```js
async function collect(target, findCandidates) {
  const seen = new Set();
  let round = 0;
  while (seen.size < target) {
    round++;
    const candidates = await findCandidates();
    const newItems = candidates.filter(item => !seen.has(item));
    newItems.forEach(item => seen.add(item));
    console.log(`Round ${round}: added ${newItems.length} new items (${seen.size}/${target} total)`);
  }
  return Array.from(seen).slice(0, target);
}

module.exports = { collect };
```

